import{_ as r,C as o,o as n,c as d,aj as e,E as s}from"./framework.js";const f=JSON.parse('{"title":"商品管理（列表） | Cms / Commerce | Documentation","description":"商品管理（列表） in Kooboo: 维护站点可售商品的 列表、筛选与入口；单条商品的表单与规格在 商品详情（新建与编辑） 维护。","frontmatter":{"title":"商品管理（列表） | Cms / Commerce | Documentation","description":"商品管理（列表） in Kooboo: 维护站点可售商品的 列表、筛选与入口；单条商品的表单与规格在 商品详情（新建与编辑） 维护。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/commerce/product-management.html"}]]},"headers":[],"relativePath":"zh/cms/commerce/product-management.md","filePath":"cms/commerce/product-management.md","lastUpdated":1780387475000}'),m={name:"zh/cms/commerce/product-management.md"};function c(l,t,i,h,g,p){const a=o("DocImage");return n(),d("div",null,[t[0]||(t[0]=e('<h1 id="商品管理-列表" tabindex="-1">商品管理（列表） <a class="header-anchor" href="#商品管理-列表" aria-label="Permalink to &quot;商品管理（列表）&quot;">​</a></h1><blockquote><p>菜单：<strong>电商 → 商品管理</strong><br> 深链：<code>/_Admin/commerce/product-management?SiteId={站点GUID}</code></p></blockquote><p>维护站点可售商品的 <strong>列表、筛选与入口</strong>；单条商品的表单与规格在 <a href="./product-management-detail.html">商品详情（新建与编辑）</a> 维护。</p><div class="tip custom-block"><p class="custom-block-title">前置</p><p>须已有 <a href="./product-types.html">商品类型</a>；分类可选，见 <a href="./product-categories.html">商品分类</a>。全局开关与自定义字段见 <a href="./settings.html">设置</a>。</p></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>在 <a href="./../navigation.html#权限与编辑菜单">编辑菜单</a> 中勾选 <strong>电商 → 商品管理</strong>（及父级 <strong>电商</strong>）。</li><li>左侧 <strong>电商 → 商品管理</strong>。</li></ol><h2 id="列表页" tabindex="-1">列表页 <a class="header-anchor" href="#列表页" aria-label="Permalink to &quot;列表页&quot;">​</a></h2><p>路径：<code>/_Admin/commerce/product-management?SiteId=...</code></p><table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td>统计</td><td>缺货数、商品总数、库存合计等</td></tr><tr><td>筛选</td><td>关键词、上架状态、库存状态等；点击 <strong>搜索</strong> 刷新</td></tr><tr><td>表格列</td><td>由 <a href="./product-types.html">商品类型</a> 与 <a href="./settings.html">设置</a> 中的 <strong>商品自定义字段</strong> 决定；常见有标题、主图、规格数、库存、销量、标签、分类</td></tr><tr><td><strong>创建商品</strong></td><td>下拉：空白商品，或指定 <strong>商品类型</strong> 后进入 <a href="./product-management-detail.html#如何进入">新建页</a></td></tr><tr><td><strong>编辑</strong></td><td>行内铅笔进入 <a href="./product-management-detail.html#如何进入">编辑页</a></td></tr><tr><td><strong>复制</strong></td><td>勾选 <strong>一行</strong> 后，表格上方出现 <strong>复制</strong>，确认后生成副本</td></tr><tr><td><strong>批量删除</strong></td><td>勾选多行后，表格工具栏 <strong>删除</strong>；确认后移除所选商品</td></tr></tbody></table>',9)),s(a,{src:"/cms/commerce/product-management-list.png",alt:"商品管理列表：统计、筛选、商品表格与创建商品下拉",width:"1120"}),t[1]||(t[1]=e('<div class="tip custom-block"><p class="custom-block-title">规格（Variants）</p><p>若 <a href="./settings.html">设置</a> 未开启「隐藏规格」，列表会显示规格数量；规格明细在 <a href="./product-management-detail.html">商品详情</a> 页维护。</p></div><h2 id="数字商品" tabindex="-1">数字商品 <a class="header-anchor" href="#数字商品" aria-label="Permalink to &quot;数字商品&quot;">​</a></h2><p>数字商品（电子书、软件授权、可下载资源等）须先具备 <strong>数字商品</strong> 类型的 <a href="./product-types.html#数字商品">商品类型</a>，再在列表中创建或编辑具体商品。</p><table tabindex="0"><thead><tr><th>步骤</th><th>在哪里做</th></tr></thead><tbody><tr><td>1. 定义类型</td><td><a href="./product-types.html">商品类型</a> — 勾选 <strong>数字商品</strong>，可选下载次数/天数限制</td></tr><tr><td>2. 创建商品</td><td>本页 <strong>创建商品</strong> → 选择该类型（或编辑已有数字商品）</td></tr><tr><td>3. 配置交付内容</td><td><a href="./product-management-detail.html#数字商品">商品详情</a> — 在变体表格 <strong>数字产品</strong> 列，为 <strong>每个 SKU</strong> 添加文件 / 链接 / 文本</td></tr></tbody></table><p>列表摘要区或表格中，数字商品常带 <strong>数字产品</strong> 小标签（<code>isDigital</code>），便于与实体商品区分。具体交付项不在列表维护，点 <strong>编辑</strong> 进入详情页操作。</p><p>若 <a href="./settings.html">设置</a> 开启 <strong>数字商品交付项必填</strong>，未给任一变体配置交付内容的商品 <strong>无法保存</strong>。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./product-management-detail.html">商品详情（新建与编辑）</a> — <a href="./product-management-detail.html#数字商品">数字商品配置</a></li><li><a href="./product-types.html">商品类型</a> — <a href="./product-types.html#数字商品">数字商品类型</a></li><li><a href="./product-categories.html">商品分类</a></li><li><a href="./">电商概述</a></li></ul>',8))])}const _=r(m,[["render",c]]);export{f as __pageData,_ as default};
